import React from "react";
import { formatLabel } from "../../lib/reportData";
const SeverityBadge = ({ severity }) => {
  return (
    <span className={`severity severity-${severity.toLowerCase()}`}>
      <i />
      {formatLabel(severity)}
    </span>
  );
};
export default SeverityBadge;
